mapper.select:
SELECT COUNT(*) AS policy_count, IFNULL(SUM(premium), 0) AS total_premium, SUM(CASE WHEN revenue_confirmed = '1' THEN 1 ELSE 0 END) AS confirmed_count, IFNULL(SUM(CASE WHEN revenue_confirmed = '1' THEN premium ELSE 0 END), 0) AS confirmed_premium FROM jonlink_insurance_ledger WHERE 1 = 1
AND ledger_date >= #{startDate}
AND ledger_date <= #{endDate}
